svg.script:
const size = 100;
const width = 1;
const spacing = 5;
const tries = 10000;

const svg = document.currentScript.closest("svg");
svg.setAttribute("viewBox", `0 0 ${size} ${size}`);
svg.setAttribute("stroke-width", width);
const ns = "http://www.w3.org/2000/svg";

const random = (min, max) => Math.random() * (max - min) + min;
const sample = (array) => array[Math.floor(Math.random() * array.length)];
const randomPoint = () => [random(0, size), random(0, size)];
const distance = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1]);

const points = [];

for (let point = 0; point < 100; point++) {
  let point;
  for (let _try = 0; _try < tries; _try++) {
    point = randomPoint();
    if (points.every((p) => distance(p, point) > spacing)) {
      points.push(point);
      break;
    }
  }
}

for (const a of points) {
  const angle = random(0, 2 * Math.PI);
  const distance = sample([1, 1, 1, 1, 1, 3]);
  const b = [
    a[0] + Math.sin(angle) * distance,
    a[1] + Math.cos(angle) * distance,
  ];
  const line = document.createElementNS(ns, "line");
  line.setAttribute("x1", a[0]);
  line.setAttribute("y1", a[1]);
  line.setAttribute("x2", b[0]);
  line.setAttribute("y2", b[1]);
  svg.append(line);
}

svg.addEventListener("dblclick", () => {
  const clone = svg.cloneNode(true);
  clone.querySelector("script").remove();
  const blob = new Blob([clone.outerHTML], { type: "image/svg+xml" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "paper";
  a.click();
  URL.revokeObjectURL(url);
});
